COMMENT ON TABLE portal."tools_projects" IS 'tools.projects_db (SavedToolProject)';
CREATE TABLE IF NOT EXISTS portal."transactions" (
    "id" TEXT NOT NULL,
    "code" TEXT,
    "transaction_type" TEXT,
    "property_ref" JSONB,
    "property_title" JSONB,
    "buyer_name" JSONB,
    "seller_name" JSONB,
    "buyer_id" JSONB,
    "seller_id" JSONB,
    "listing_agent_id" JSONB,
    "selling_agent_id" JSONB,
    "price" DOUBLE PRECISION,
    "currency" TEXT,
    "commission_rate" JSONB,
    "stage" TEXT,
    "status" TEXT,
    "source" TEXT,
    "milestones" JSONB,
    "terms" JSONB,
    "document_text" JSONB,
    "notes" JSONB,
    "risk_flags" TEXT[],
    "created_at" TEXT,
    "updated_at" TEXT,
    "closed_at" JSONB,
    PRIMARY KEY ("id")
);
COMMENT ON TABLE portal."transactions" IS 'transactions.transactions_db (Transaction)';
CREATE TABLE IF NOT EXISTS portal."transactions_offers" (
    "id" TEXT NOT NULL,
    "transaction_id" TEXT NOT NULL,
    "price" DOUBLE PRECISION NOT NULL,
    "buyer_name" JSONB,
    "terms" JSONB,
    "status" TEXT,
    "counter_price" JSONB,
    "created_at" TEXT,
    PRIMARY KEY ("id")
);
COMMENT ON TABLE portal."transactions_offers" IS 'transactions.offers_db (Offer)';
CREATE TABLE IF NOT EXISTS portal."transactions_signatures" (
    "id" TEXT NOT NULL,
    "transaction_id" TEXT NOT NULL,
    "signer" TEXT NOT NULL,
    "role" TEXT,
    "method" TEXT,
    "signed" BOOLEAN,
    "signed_at" JSONB,
    "reference" JSONB,
    PRIMARY KEY ("id")
);
COMMENT ON TABLE portal."transactions_signatures" IS 'transactions.signatures_db (Signature)';

